% Observables at thermal equilibrium using the three formalisms 
% supported by Spinach kernel, tested against known answers.
%
% i.kuprov@soton.ac.uk

function thermal_equilibrium_1()

% Spin system parameters
sys.magnet=14.1;
sys.isotopes={'E','1H','14N','15N'};
inter.zeeman.scalar={2.0023 1.0 2.0 3.0};
inter.coupling.scalar=cell(length(sys.isotopes));
inter.coupling.scalar{1,2}=1e6;
inter.coupling.scalar{2,3}=1e6;
inter.coupling.scalar{1,3}=1e3;
inter.coupling.scalar{3,4}=1e3;
inter.coupling.scalar{1,4}=1e2;
inter.temperature=4.2;

% Preallocate the answers
eq_mags_spinach=zeros(4,3,'like',1i);
eq_mags_textbook=zeros(4,1,'like',1i);

% Get numerical equilibrium magnetisation
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
for n=1:numel(formalisms)
    bas.formalism=formalisms{n};
    bas.approximation='none';
    spin_system=create(sys,inter);
    spin_system=basis(spin_system,bas);
    rho=equilibrium(spin_system,hamiltonian(assume(spin_system,'labframe'),'left'));
    eq_mags_spinach(1,n)=trace(state(spin_system,'Lz','E')'*rho);
    eq_mags_spinach(2,n)=trace(state(spin_system,'Lz','1H')'*rho);
    eq_mags_spinach(3,n)=trace(state(spin_system,'Lz','14N')'*rho);
    eq_mags_spinach(4,n)=trace(state(spin_system,'Lz','15N')'*rho);
end

% Get analytical equilibrium magnetisation
[~,P]=levelpop('E',sys.magnet,inter.temperature);
eq_mags_textbook(1)=0.5*P(1)-0.5*P(2);
[~,P]=levelpop('1H',sys.magnet,inter.temperature);
eq_mags_textbook(2)=0.5*P(1)-0.5*P(2);
[~,P]=levelpop('14N',sys.magnet,inter.temperature);
eq_mags_textbook(3)=P(1)-P(3);
[~,P]=levelpop('15N',sys.magnet,inter.temperature);
eq_mags_textbook(4)=0.5*P(1)-0.5*P(2);

% Display the answers
if any(abs(eq_mags_spinach-eq_mags_textbook)>1e-5,'all')
    error('Cross-formalism thermal equilibrium test FAILED.');
else
    disp('Cross-formalism thermal equilibrium test PASSED.');
end

end

% Thermal equilibrium states, using all the different formalisms 
% supported by Spinach kernel.
%
% i.kuprov@soton.ac.uk

function thermal_equilibrium_2()

% Spin system parameters
sys.magnet=14.1;
sys.isotopes={'E','1H','14N','15N'};
inter.zeeman.scalar={2.0023 1.0 2.0 3.0};
inter.coupling.scalar=cell(length(sys.isotopes));
inter.coupling.scalar{1,2}=1e6;
inter.coupling.scalar{2,3}=1e6;
inter.coupling.scalar{1,3}=1e3;
inter.coupling.scalar{3,4}=1e3;
inter.coupling.scalar{1,4}=1e2;
inter.temperature=4.2;

% Get thermal equilibrium states at finite temperature
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};
rho=cell(1,numel(formalisms));
for n=1:numel(formalisms)
    bas.formalism=formalisms{n}; bas.approximation='none';
    spin_system=create(sys,inter); spin_system=basis(spin_system,bas);
    rho{n}=equilibrium(spin_system,hamiltonian(assume(spin_system,'labframe'),'left'));
end

% Zeeman-liouv to zeeman-hilb
rho{2}=reshape(rho{2},[24 24]);

% Sphten-liouv to zeeman-hilb
mult_factor=sqrt(prod(spin_system.comp.mults));
rho{3}=sphten2zeeman(spin_system)*rho{3};
rho{3}=reshape(rho{3},[24 24])/mult_factor;

% Check the differences
if (norm(rho{1}-rho{2},2)>1e-8)||(norm(rho{2}-rho{3},2)>1e-8)
    error('Cross-formalism thermal equilibrium test FAILED.');
else
    disp('Cross-formalism thermal equilibrium test PASSED.');
end

end

% Test of the thermal equilibrium functionality against the 
% textbook expressions for the Boltzmann populations.
%
% i.kuprov@soton.ac.uk

function thermal_equilibrium_3()

% X-band magnet
sys.magnet=0.34;

% Electron and two protons
sys.isotopes={'E','1H','1H'};

% Zeeman interactions (g-tensor for trityl, ppm guess for 1H)
inter.zeeman.eigs={[2.00319 2.00319 2.00258],[0 0 5],[0 5 0]};
inter.zeeman.euler=(pi/180)*{[0 10 0],[0 0 10],[100 0 0]};

% Cartesian coordinates
inter.coordinates={[0.000 0.000 0.000];
                   [0.000 3.500 0.000];
                   [2.475 2.475 0.000]};

% Spin temperature
inter.temperature=80;

% Formalisms to test
formalisms={'zeeman-hilb','zeeman-liouv','sphten-liouv'};

% Loop over formalisms
for n=1:numel(formalisms)

    % Basis set
    bas.formalism=formalisms{n};
    bas.approximation='none';

    % Spinach housekeeping
    spin_system=create(sys,inter);
    spin_system=basis(spin_system,bas);

    % Thermal equilibrium state
    H=hamiltonian(assume(spin_system,'labframe'),'left');
    rho_eq=equilibrium(spin_system,H);

    % Detection states
    coil_a=state(spin_system,{'Lz'},{1});
    coil_b=state(spin_system,{'Lz'},{2});
    coil_c=state(spin_system,{'Lz'},{3});

    % Get the expectation values from Spinach
    expt_a_spinach=trace(coil_a'*rho_eq);
    expt_b_spinach=trace(coil_b'*rho_eq);
    expt_c_spinach=trace(coil_c'*rho_eq);

    % Get the expectation values from textbook
    [~,PE]=levelpop('E',sys.magnet,inter.temperature);
    [~,PH]=levelpop('1H',sys.magnet,inter.temperature);
    expt_a_textbook=0.5*PE(1)-0.5*PE(2);
    expt_b_textbook=0.5*PH(1)-0.5*PH(2);
    expt_c_textbook=0.5*PH(1)-0.5*PH(2);

    % Test for differences
    if (abs((expt_a_spinach-expt_a_textbook)/expt_a_textbook)>1e-3)||...
       (abs((expt_b_spinach-expt_b_textbook)/expt_b_textbook)>1e-3)||...
       (abs((expt_c_spinach-expt_c_textbook)/expt_c_textbook)>1e-3)
        error('Thermodynamic equilibrium test FAILED.');
    end

end

% Report success
disp('Thermodynamic equilibrium tests PASSED.');

end

