% Modifies the relaxation superoperator to drive the system to the user-
% specified target state (inhomogeneous master equation formalism) or to
% the equilibrium state of the lab frame Hamiltonian at the temperature
% provided by the user (DiBari-Levitt formalism). Syntax:
%
%           R=thermalize(spin_system,R,HLSPS,T,rho_eq,method)
%
% Parameters:
%
%     R       - symmetric negative definite relaxation super-
%               operator that drives the system towards the
%               zero state vector; this may be obtained from
%               relaxation.m if inter.equilibrium is 'zero'
%
%     HLSPS   - lab frame Hamiltonian left side product super-
%               operator, available from hamiltonian.m (also
%               call orientation.m if necessary); this is not
%               required for IME formalism (pass empty array)
%
%     T       - absolute temperature, not required for the 
%               IME formalism (pass empty array)
%
%     rho_eq  - thermal equilibrium state, not required for 
%               the DiBari-Levitt formalism (pass empty array)
%
%     method  - 'dibari' for DiBari-Levitt thermalisation,
%               'IME' for the inhomogeneous master equation
%
% Outputs:
%
%     R       - thermalized relaxation superoperator
%
% Note: IME requires a target state with non-zero unit-state population.
%       The correction is normalized internally, so the overall scaling
%       of the supplied target state is immaterial.
%
% Note: DiBari-Levitt method is computationally expensive, but tends to
%       work better than IME, particularly in exotic regimes.
%
% i.kuprov@soton.ac.uk
%
% <https://spindynamics.org/wiki/index.php?title=thermalize.m>

function R=thermalize(spin_system,R,HLSPS,T,rho_eq,method)

% Check consistency
grumble(spin_system,R,HLSPS,T,rho_eq,method);

% Get the unit state
unit=unit_state(spin_system);

% Choose the method
switch method

    case 'IME'

        % Normalize the unit-state functional on the target state.  The
        % Euclidean normalization of the unit state is representation
        % dependent, whereas a physical equilibrium density operator has
        % unit trace in every representation.
        unit_population=unit'*rho_eq;

        % Apply IME correction
        R=R-kron(unit'/unit_population,R*rho_eq);

    case 'dibari'

        % Get the temperature factor
        beta=spin_system.tols.hbar/(spin_system.tols.kbol*T);

        % Modify the relaxation superoperator
        R=R*propagator(spin_system,HLSPS,1i*beta);

    otherwise

        % Complain and bomb out
        error('unknown thermalization method.');

end

end

% Consistency enforcement
function grumble(spin_system,R,HLSPS,T,rho_eq,method)
if (~isnumeric(R))||(size(R,1)~=size(R,2))
    error('R must be a square matrix.');
end
unit=unit_state(spin_system);
if norm(R*unit,2)>1e-10
    error('R appears to be thermalized already.');
end
if ~ischar(method)
    error('method must be a character string.');
end
if strcmp(method,'IME')
    if isempty(rho_eq)
        error('rho_eq cannot be empty for IME formalism.');
    end
    if (~isnumeric(rho_eq))||(~iscolumn(rho_eq))
        error('rho_eq must be a column vector.');
    end
    if abs(unit'*rho_eq)<1e-10
        error('rho_eq must have a non-zero unit state population.');
    end
end
if strcmp(method,'dibari')
    if isempty(HLSPS)
        error('HLSPS cannot be empty for DiBari-Levitt formalism.');
    end
    if (~isnumeric(HLSPS))||(size(HLSPS,1)~=size(HLSPS,2))
        error('HLSPS must be a square matrix.');
    end
    if norm(HLSPS*unit,2)<1e-8
        error('HLSPS appears to be a commutation superoperator.');
    end
    if isempty(T)
        error('T cannot be empty for DiBari-Levitt formalism.');
    end
    if (~isnumeric(T))||(~isreal(T))||(~isscalar(T))||(T<=0)
        error('T must be a positive real scalar.');
    end
end
end

% Tretyakov, the owner of the famous picture gallery in St Petersburg, had
% ordered the guards not to let Ilya Repin, a famous painter, into the gal-
% lery after Repin was repeatedly seen turning up with brushes and paints,
% and making small fixes to his works that the gallery had bought.
%
% <https://spindynamics.org/wiki/index.php?title=relaxation.m>

function R=relaxation(spin_system,euler_angles)

% Set defaults
spin_system=defaults(spin_system);

% Check consistency
grumble(spin_system);

% Get the matrix going
R=mprealloc(spin_system,0);

% Keep non-selective damping separate from relaxation theories whose
% cross-relaxation terms may subsequently be discarded.  In some Liouville
% representations, protecting the unit state introduces off-diagonal matrix
% elements even though non-selective damping is physically diagonal.  Those
% representation-induced elements must not be removed by rlx_keep.
R_damp=mprealloc(spin_system,0);

% Do nothing if none specified
if isempty(spin_system.rlx.theories)

    % Update the user
    report(spin_system,'relaxation superoperator set to zero.');

    % Exit the function
    return;

end

% Add non-selective damping terms
if ismember('damp',spin_system.rlx.theories)

    % Anisotropic damping option
    if exist('euler_angles','var')

        % Update the user
        report(spin_system,'adding anisotropic non-selective damping terms:');

        % Compute orientation ort (this matches alphas=0 of two-angle grids)
        ort=[0 0 1]*euler2dcm(euler_angles(1),euler_angles(2),euler_angles(3));

        % Get the rate at the current orientation
        rate=ort*spin_system.rlx.damp_rate*ort';

    else

        % Update the user
        report(spin_system,'adding isotropic non-selective damping terms:');
        if ~isscalar(spin_system.rlx.damp_rate)
            report(spin_system,'   WARNING - damping rate anisotropy ignored');
        end

        % Get the isotropic part of the rate
        rate=mean(diag(spin_system.rlx.damp_rate));

    end

    % Build the relaxation matrix
    switch spin_system.bas.formalism

        case {'zeeman-hilb'}

            % Update the user
            report(spin_system,'   Hilbert space - unit state will be damped');

            % Damp everything
            R_damp=R_damp-(rate/2)*unit_oper(spin_system);

        case {'zeeman-liouv','sphten-liouv'}

            % Update the user
            report(spin_system,'   Liouville space - unit state will not be damped');

            % Damp everything at the rate specified
            R_damp=R_damp-rate*unit_oper(spin_system);

            % Make sure the unit state is not damped
            U=unit_state(spin_system);
            R_damp=R_damp-(U'*R_damp*U)*(U*U');

    end

end

% Include damping in the complete-superoperator diagnostics and in dynamic
% frequency shift processing below.
R=R+R_damp;

% Add extended T1/T2 model terms
if ismember('t1_t2',spin_system.rlx.theories)

    % Call the extended T1/T2 model function
    if exist('euler_angles','var')
        report(spin_system,'adding anisotropic extended T1/T2 model terms...');
        [R1,R2]=rlx_t1_t2(spin_system,euler_angles);
    else
        report(spin_system,'adding isotropic extended T1/T2 model terms...');
        [R1,R2]=rlx_t1_t2(spin_system); 
    report(spin_system,'SRSK relaxation theory terms have been incorporated.');

end

% Print matrix density statistics
report(spin_system,['full relaxation superoperator density ' num2str(100*nnz(R)/numel(R))...
                    '%, nnz ' num2str(nnz(R)) ', sparsity ' num2str(issparse(R))]);

% Decide the fate of dynamic frequency shifts
switch spin_system.rlx.dfs

    case 'keep'

        % Do nothing and inform the user
        report(spin_system,'dynamic frequency shifts have been kept.');

    case 'ignore'

        % Kill the dynamic frequency shifts
        R=real(R);

        % Inform the user
        report(spin_system,'dynamic frequency shifts have been ignored.');

    otherwise

        % Complain and bomb out
        error('invalid value of the inter.rlx_dfs parameter.');

end

% Decide the fate of the off-diagonal components
R=R-R_damp;
switch spin_system.rlx.keep

    case 'diagonal'

        % Pull out the diagonal
        R=diag(diag(R));

        % Inform the user
        report(spin_system,'all cross-relaxation terms have been ignored.');

    case 'kite'

        % Refuse to process inappropriate cases
        if ~strcmp(spin_system.bas.formalism,'sphten-liouv')
            error('kite option is only available for sphten-liouv formalism.');
        end

        % Compile the index of all longitudinal spin orders
        [~,M]=lin2lm(spin_system.bas.basis);
        long_states=find(sum(abs(M),2)==0);

        % Index the relaxation superoperator
        [rows,cols,vals]=find(R);

        % Keep self-relaxation and longitudinal cross-relaxation terms
        vals=vals.*((ismember(rows,long_states)&ismember(cols,long_states))|(rows==cols));

        % Recompose the relaxation superoperator
        R=sparse(rows,cols,vals,length(R),length(R)); clear('rows','cols','vals');

        % Inform the user
        report(spin_system,'transverse cross-relaxation terms have been ignored.');

    case 'secular'

        % Refuse to process inappropriate cases
        if ~strcmp(spin_system.bas.formalism,'sphten-liouv')
            error('secular option is only available for sphten-liouv formalism.');
        end

        % Compute base frequencies of basis states
        [~,M]=lin2lm(spin_system.bas.basis);
        frequencies=sum(spin_system.inter.basefrqs.*M,2);

        % Index the relaxation superoperator
        [rows,cols,vals]=find(R);

        % Set the initial keep mask
        keep_mask=false(size(vals));

        % Loop over unique frequencies
        for omega=unique(frequencies)'

            % Find the states having the current frequency
            current_frq_group=find(frequencies==omega);

            % Update the keep mask
            keep_mask=keep_mask|(ismember(rows,current_frq_group)&...
                                 ismember(cols,current_frq_group));

        end

        % Recompose the relaxation superoperator
        R=sparse(rows,cols,vals.*keep_mask,length(R),length(R));

        % Inform the user
        report(spin_system,'secular approximation wrt Zeeman Hamiltonian...');
        report(spin_system,'non-secular cross-relaxation terms have been ignored.');

        % Do garbage collection
        clear('rows','cols','vals');

    case 'labframe'

        % Inform the user
        report(spin_system,'returning complete relaxation superoperator (lab frame simulations only).');

end

% Add non-selective damping after cross-relaxation term selection
R=R+R_damp;

% Choose the thermalisation model
switch spin_system.rlx.equilibrium

    case 'zero'

        % Do nothing and inform the user
